section.sketch:
let objet1 = "épée";
let objet2 = "corde";
let objet3 = "torche";

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(600, 500, 150);

  fill(240);
  textSize(20);
  text(objet1, 50, 50);
  text(objet2, 50, 80);
  text(objet3, 50, 110);
}

let inventaire = ["épée", "corde", "torche"];
let choix = 0;

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(400, 500, 150);
  parler(inventaire[choix], 400, 230);
}

function mousePressed() {
  choix = lancerDe(3) - 1;
}

let inventaire = ["épée", "corde", "torche"];

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(600, 500, 150);

  fill(240);
  textSize(20);
  for (let i = 0; i < inventaire.length; i = i + 1) {
    text(inventaire[i], 50, 50 + i * 30);
  }
}

function mousePressed() {
  inventaire.push("potion");
}

let inventaire = ["épée", "bouclier", "corde", "torche"];

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(600, 500, 150);

  let enMain = inventaire.slice(0, 2);
  let auFond = inventaire.slice(2);

  fill(240);
  textSize(20);

  text("En main", 50, 50);
  for (let i = 0; i < enMain.length; i = i + 1) {
    text(enMain[i], 50, 90 + i * 30);
  }

  text("Dans le sac", 250, 50);
  for (let i = 0; i < auFond.length; i = i + 1) {
    text(auFond[i], 250, 90 + i * 30);
  }
}

function mousePressed() {
  inventaire.push("potion");
}

let inventaire = ["épée", "corde", "torche", "potion"];
let sorti = "";

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(600, 500, 150);

  fill(240);
  textSize(20);
  for (let i = 0; i < inventaire.length; i = i + 1) {
    text(inventaire[i], 50, 50 + i * 30);
  }

  if (sorti !== "") {
    parler(sorti, 600, 230);
  }
}

function mousePressed() {
  if (inventaire.length > 0) {
    sorti = inventaire.pop();
  }
}

let hauteurs = [120, 90, 140, 100, 130, 80, 150, 110];

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerBilly(400, 500, 250);

  fill(110, 80, 50);
  for (let i = 0; i < hauteurs.length; i = i + 1) {
    rect(40 + i * 100, 520 - hauteurs[i], 20, hauteurs[i]);
  }
}
